using System;
using System.IO;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Drawing.Imaging;
using System.Collections.Generic;
internal static class IconBuilder {
 internal static Bitmap Render(int size){var bitmap=new Bitmap(size,size,PixelFormat.Format32bppArgb);using(var g=Graphics.FromImage(bitmap)){g.SmoothingMode=SmoothingMode.AntiAlias;g.Clear(Color.Transparent);g.ScaleTransform(size/64f,size/64f);using(var path=new GraphicsPath()){path.AddArc(2,2,24,24,180,90);path.AddArc(38,2,24,24,270,90);path.AddArc(38,38,24,24,0,90);path.AddArc(2,38,24,24,90,90);path.CloseFigure();using(var brush=new SolidBrush(Color.FromArgb(22,43,64)))g.FillPath(brush,path);}using(var pen=new Pen(Color.FromArgb(239,249,255),6)){pen.StartCap=pen.EndCap=LineCap.Round;using(var arch=new GraphicsPath()){arch.AddBezier(17,35,13,9,51,9,47,35);g.DrawPath(pen,arch);}}using(var brush=new SolidBrush(Color.FromArgb(239,249,255))){g.FillRectangle(brush,12,32,10,18);g.FillRectangle(brush,42,32,10,18);}using(var pen=new Pen(Color.FromArgb(62,228,191),3)){pen.StartCap=pen.EndCap=LineCap.Round;pen.LineJoin=LineJoin.Round;g.DrawLines(pen,new[]{new PointF(26,39),new PointF(29,32),new PointF(33,46),new PointF(37,35),new PointF(40,40)});}}return bitmap;}
 internal static void Generate(string path){int[]sizes={16,24,32,48,64,128,256};var images=new List<byte[]>();foreach(int n in sizes){using(var bitmap=Render(n)){using(var memory=new MemoryStream()){if(n==256){bitmap.Save(memory,ImageFormat.Png);}else{using(var writer=new BinaryWriter(memory,System.Text.Encoding.UTF8,true)){int maskStride=((n+31)/32)*4;writer.Write(40);writer.Write(n);writer.Write(n*2);writer.Write((short)1);writer.Write((short)32);writer.Write(0);writer.Write(n*n*4+maskStride*n);writer.Write(0);writer.Write(0);writer.Write(0);writer.Write(0);for(int y=n-1;y>=0;y--)for(int x=0;x<n;x++){Color c=bitmap.GetPixel(x,y);writer.Write(c.B);writer.Write(c.G);writer.Write(c.R);writer.Write(c.A);}for(int y=n-1;y>=0;y--){byte[]mask=new byte[maskStride];for(int x=0;x<n;x++)if(bitmap.GetPixel(x,y).A==0)mask[x/8]|=(byte)(128>>(x%8));writer.Write(mask);}}}images.Add(memory.ToArray());}}}using(var stream=File.Create(path))using(var writer=new BinaryWriter(stream)){writer.Write((short)0);writer.Write((short)1);writer.Write((short)sizes.Length);int offset=6+16*sizes.Length;for(int i=0;i<sizes.Length;i++){writer.Write((byte)(sizes[i]==256?0:sizes[i]));writer.Write((byte)(sizes[i]==256?0:sizes[i]));writer.Write((byte)0);writer.Write((byte)0);writer.Write((short)1);writer.Write((short)32);writer.Write(images[i].Length);writer.Write(offset);offset+=images[i].Length;}foreach(byte[] image in images)writer.Write(image);}}
}
